Up-to-date code docs for any prompt

{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.upstash/context7",
  "description": "Up-to-date code docs for any prompt",
  "title": "Context7",
  "repository": {
    "url": "https://github.com/upstash/context7",
    "source": "github"
  },
  "version": "4.1.0",
  "websiteUrl": "https://context7.com",
  "icons": [
    {
      "src": "https://raw.githubusercontent.com/upstash/context7/master/public/icon.png",
      "mimeType": "image/png"
    }
  ],
  "packages": [
    {
      "registryType": "npm",
      "identifier": "@upstash/context7-mcp",
      "version": "4.1.0",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "description": "API key for authentication",
          "isSecret": true,
          "name": "CONTEXT7_API_KEY"
        }
      ]
    },
    {
      "registryType": "mcpb",
      "identifier": "https://github.com/upstash/context7/releases/download/mcpb-v4.1.0/context7.mcpb",
      "version": "4.1.0",
      "fileSha256": "c5483db1abe8a05ec1d83a60c5bbddabe667cda462fcb831a8709580d43bddfa",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "description": "API key for authentication",
          "isSecret": true,
          "name": "CONTEXT7_API_KEY"
        }
      ]
    }
  ],
  "remotes": [
    {
      "type": "streamable-http",
      "url": "https://mcp.context7.com/mcp",
      "headers": [
        {
          "description": "API key for authentication. Accepts \"Bearer <key>\" or the raw key.",
          "isSecret": true,
          "name": "Authorization"
        }
      ]
    }
  ]
}

Connect AI assistants to GitHub - manage repos, issues, PRs, and workflows through natural language.

{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.github/github-mcp-server",
  "description": "Connect AI assistants to GitHub - manage repos, issues, PRs, and workflows through natural language.",
  "title": "GitHub",
  "repository": {
    "url": "https://github.com/github/github-mcp-server",
    "source": "github"
  },
  "version": "1.12.1",
  "packages": [
    {
      "registryType": "oci",
      "identifier": "ghcr.io/github/github-mcp-server:1.12.1",
      "transport": {
        "type": "stdio"
      },
      "runtimeArguments": [
        {
          "description": "Publish the OAuth callback port to loopback so the in-container login callback is reachable",
          "value": "127.0.0.1:8085:8085",
          "type": "named",
          "name": "-p"
        },
        {
          "description": "Fixed OAuth callback port, matching the published port above",
          "value": "GITHUB_OAUTH_CALLBACK_PORT=8085",
          "type": "named",
          "name": "-e"
        },
        {
          "description": "Optional GitHub Personal Access Token. Omit to log in with OAuth on first use.",
          "value": "GITHUB_PERSONAL_ACCESS_TOKEN={token}",
          "variables": {
            "token": {
              "format": "string",
              "isSecret": true
            }
          },
          "type": "named",
          "name": "-e"
        }
      ]
    }
  ],
  "remotes": [
    {
      "type": "streamable-http",
      "url": "https://api.githubcopilot.com/mcp/",
      "headers": [
        {
          "description": "Authorization header with authentication token (PAT or App token)",
          "isSecret": true,
          "name": "Authorization"
        }
      ]
    }
  ]
}

